package com.example.shelter.repository;
import com.example.shelter.model.AdoptionApplication; import org.springframework.stereotype.Repository; import java.util.List;
@Repository public class AdoptionApplicationRepository { private final AdoptionApplicationJpaRepository dao; public AdoptionApplicationRepository(AdoptionApplicationJpaRepository dao){this.dao=dao;} public List<AdoptionApplication> findAll(){return dao.findAll();} public AdoptionApplication findById(Long id){return dao.findById(id).orElse(null);} public AdoptionApplication save(AdoptionApplication x){return dao.save(x);} public void deleteById(Long id){dao.deleteById(id);} public List<AdoptionApplication> findByAnimalId(Long id){return dao.findByAnimalId(id);} public List<AdoptionApplication> findByApplicantId(Long id){return dao.findByApplicantId(id);} }
